namespace Armada.Runtimes.Usage
{
    using System;
    using System.Collections.Generic;
    using System.ComponentModel;
    using System.IO;
    using System.Text.Json;
    using System.Text.Json.Serialization;
    using System.Threading;
    using System.Threading.Tasks;
    using Armada.Core.Enums;
    using Armada.Core.Protocol;
    using Armada.Core.Services;

    /// <summary>
    /// Codex account usage through a local <c>codex app-server</c> JSON-RPC session over stdio (verified from
    /// the schema generated by the installed binary, see PROBE_INTERFACES.md): <c>initialize</c> with
    /// <c>clientInfo</c>, the <c>initialized</c> notification, then <c>account/rateLimits/read</c>. No thread or
    /// turn is ever created, so no model is invoked. The session runs on the credential host; the provider
    /// account id is HMAC-ed there and never leaves it raw. Every line and the whole session are byte-capped,
    /// a truncated or oversized answer is refused, and the helper's process tree is always terminated in
    /// <c>finally</c>, including on timeout and cancellation.
    /// </summary>
    public class CodexUsageProbe : IUsageProbe
    {
        #region Public-Members

        /// <summary>
        /// Longest accepted JSON-RPC line, in bytes.
        /// </summary>
        public const int MaximumLineBytes = 64 * 1024;

        /// <summary>
        /// Most stdout bytes accepted from one session.
        /// </summary>
        public const int MaximumSessionBytes = 256 * 1024;

        /// <summary>
        /// Most lines read while waiting for one response (notifications are skipped).
        /// </summary>
        public const int MaximumLinesPerResponse = 64;

        /// <summary>
        /// Process id of the most recent helper session, or 0. Exposed so tests can prove forced cleanup.
        /// </summary>
        public int LastProcessId { get; private set; } = 0;

        #endregion

        #region Private-Members

        private const long _InitializeId = 1;
        private const long _ReadId = 2;
        private readonly UsageAccountResolver _Accounts;
        private readonly string _Executable;
        private readonly List<string> _Arguments;
        private readonly Func<DateTime> _Clock;

        private static readonly JsonSerializerOptions _WriteOptions = new JsonSerializerOptions
        {
            DefaultIgnoreCondition = JsonIgnoreCondition.Never
        };

        #endregion

        #region Constructors-and-Factories

        /// <summary>
        /// Instantiate.
        /// </summary>
        /// <param name="accounts">Host-local account resolver that derives the opaque account key.</param>
        /// <param name="executable">Codex executable; defaults to <c>codex</c> on PATH.</param>
        /// <param name="arguments">Arguments; defaults to <c>app-server</c> (stdio is its default transport).</param>
        /// <param name="clock">Optional UTC clock seam for tests.</param>
        /// <exception cref="ArgumentNullException">Thrown when <paramref name="accounts"/> is null.</exception>
        public CodexUsageProbe(UsageAccountResolver accounts, string? executable = null, IEnumerable<string>? arguments = null, Func<DateTime>? clock = null)
        {
            _Accounts = accounts ?? throw new ArgumentNullException(nameof(accounts));
            _Executable = String.IsNullOrWhiteSpace(executable) ? "codex" : executable.Trim();
            _Arguments = arguments == null ? new List<string> { "app-server" } : new List<string>(arguments);
            _Clock = clock ?? (() => DateTime.UtcNow);
        }

        #endregion

        #region Public-Methods

        /// <inheritdoc />
        public async Task<UsageProbeResult> CaptureAsync(UsageProbeHost host, CancellationToken token = default)
        {
            if (host == null) throw new ArgumentNullException(nameof(host));

            UsageProcessSession session;
            try
            {
                session = UsageProcessSession.Start(_Executable, _Arguments, MaximumLineBytes, MaximumSessionBytes);
            }
            catch (Win32Exception)
            {
                return UsageProbeResult.Unsupported("RuntimeNotInstalled", "the codex CLI is not installed or not on PATH on this host");
            }
            catch (Exception e)
            {
                return UsageProbeResult.Failed("CommandStartFailed", SecretRedactor.Redact("codex app-server could not start: " + e.Message));
            }

            LastProcessId = session.ProcessId;
            using (session)
            {
                try
                {
                    await session.WriteLineAsync(Serialize(new InitializeRequest()), token).ConfigureAwait(false);
                    ResponseRead initialize = await ReadResponseAsync(session, _InitializeId, token).ConfigureAwait(false);
                    if (initialize.Failure != null) return initialize.Failure;

                    await session.WriteLineAsync(Serialize(new InitializedNotification()), token).ConfigureAwait(false);
                    await session.WriteLineAsync(Serialize(new RateLimitsReadRequest()), token).ConfigureAwait(false);
                    ResponseRead read = await ReadResponseAsync(session, _ReadId, token).ConfigureAwait(false);
                    if (read.Failure != null) return read.Failure;

                    DateTime observedUtc = _Clock();
                    CodexJsonRpcResponse<CodexRateLimitsReadResponse>? response;
                    try
                    {
                        response = JsonSerializer.Deserialize<CodexJsonRpcResponse<CodexRateLimitsReadResponse>>(read.Line!);
                    }
                    catch (JsonException)
                    {
                        return UsageProbeResult.Failed("MalformedOutput", "the app-server rate-limit answer is not valid JSON");
                    }

                    UsageProbeResult result = CodexRateLimitUsage.ToResult(response?.Result, observedUtc);
                    string? accountId = response?.Result?.AccountId;
                    if (result.Status == UsageSnapshotStatusEnum.Ok)
                        result.AccountKey = _Accounts.DeriveAccountKey(host.TenantId, host.Runtime, accountId, null);
                    return result;
                }
                catch (IOException)
                {
                    return UsageProbeResult.Failed("TruncatedOutput", "codex app-server closed its pipes before answering");
                }
            }
        }

        #endregion

        #region Private-Methods

        private static string Serialize<T>(T value)
        {
            return JsonSerializer.Serialize(value, _WriteOptions);
        }

        private static async Task<ResponseRead> ReadResponseAsync(UsageProcessSession session, long id, CancellationToken token)
        {
            for (int i = 0; i < MaximumLinesPerResponse; i++)
            {
                UsageProcessLine line = await session.ReadLineAsync(token).ConfigureAwait(false);
                switch (line.Kind)
                {
                    case UsageProcessLineKindEnum.Oversize:
                        return ResponseRead.Fail(UsageProbeResult.Failed("MalformedOutput", "codex app-server wrote more than the accepted output"));
                    case UsageProcessLineKindEnum.Truncated:
                        return ResponseRead.Fail(UsageProbeResult.Failed("TruncatedOutput", "codex app-server ended its output in the middle of an answer"));
                    case UsageProcessLineKindEnum.EndOfStream:
                        return ResponseRead.Fail(UsageProbeResult.Failed("TruncatedOutput", "codex app-server exited before answering"));
                }

                if (String.IsNullOrWhiteSpace(line.Text)) continue;
                CodexJsonRpcEnvelope? envelope;
                try
                {
                    envelope = JsonSerializer.Deserialize<CodexJsonRpcEnvelope>(line.Text);
                }
                catch (JsonException)
                {
                    return ResponseRead.Fail(UsageProbeResult.Failed("MalformedOutput", "codex app-server wrote a line that is not JSON-RPC"));
                }

                // Notifications (including a passive account/rateLimits/updated push), server requests and
                // unrelated responses are skipped; only the answer to this request id is used.
                if (envelope == null || !String.IsNullOrEmpty(envelope.Method) || envelope.Id == null || envelope.Id.Value != id) continue;
                if (envelope.Error != null) return ResponseRead.Fail(Classify(envelope.Error));
                return ResponseRead.Ok(line.Text);
            }

            return ResponseRead.Fail(UsageProbeResult.Failed("MalformedOutput", "codex app-server did not answer within the accepted number of lines"));
        }

        private static UsageProbeResult Classify(CodexJsonRpcError error)
        {
            string message = SecretRedactor.Redact(error.Message ?? "codex app-server reported an error");
            string lower = message.ToLowerInvariant();
            if (lower.Contains("auth") || lower.Contains("login") || lower.Contains("logged in") || lower.Contains("unauthorized")
                || lower.Contains("401") || lower.Contains("403") || lower.Contains("credential"))
                return UsageProbeResult.AuthMissing("CredentialUnavailable", message);
            return UsageProbeResult.Failed("ProviderError", message);
        }

        #endregion

        #region Private-Types

        private sealed class ResponseRead
        {
            public string? Line { get; set; } = null;

            public UsageProbeResult? Failure { get; set; } = null;

            public static ResponseRead Ok(string line)
            {
                return new ResponseRead { Line = line };
            }

            public static ResponseRead Fail(UsageProbeResult failure)
            {
                return new ResponseRead { Failure = failure };
            }
        }

        private sealed class ClientInfo
        {
            [JsonPropertyName("name")]
            public string Name { get; set; } = "armada-usage-probe";

            [JsonPropertyName("title")]
            public string? Title { get; set; } = null;

            [JsonPropertyName("version")]
            public string Version { get; set; } = "1.0.0";
        }

        private sealed class InitializeCapabilities
        {
            [JsonPropertyName("experimentalApi")]
            public bool ExperimentalApi { get; set; } = false;
        }

        private sealed class InitializeParams
        {
            [JsonPropertyName("clientInfo")]
            public ClientInfo ClientInfo { get; set; } = new ClientInfo();

            [JsonPropertyName("capabilities")]
            public InitializeCapabilities Capabilities { get; set; } = new InitializeCapabilities();
        }

        private sealed class InitializeRequest
        {
            [JsonPropertyName("method")]
            public string Method { get; set; } = "initialize";

            [JsonPropertyName("id")]
            public long Id { get; set; } = _InitializeId;

            [JsonPropertyName("params")]
            public InitializeParams Params { get; set; } = new InitializeParams();
        }

        private sealed class InitializedNotification
        {
            [JsonPropertyName("method")]
            public string Method { get; set; } = "initialized";
        }

        private sealed class RateLimitsReadRequest
        {
            [JsonPropertyName("method")]
            public string Method { get; set; } = "account/rateLimits/read";

            [JsonPropertyName("id")]
            public long Id { get; set; } = _ReadId;
        }

        #endregion
    }
}
